-- 004_readmodel_edge_constraints.sql — Task1570 readmodel_edge 治理
-- 背景：1547 审出 readmodel_edge 14.99 万行无任何约束、8412 行完全同内容冗余
-- （wikilink 按出现次数插行，evidence 无出现序号 → 纯冗余）。
-- 本迁移：①去重（保留每组最早物理行 min ctid）②evidence SET NOT NULL（0 NULL 已勘察）
-- ③代理主键 id（GENERATED BY DEFAULT，pg_dump 恢复可显式插值）
-- ④业务唯一键 = 写入方语义（refresh_readmodel.py 代际替换+按内容元组投影，
--   约束=(src_identity,dst_identity,edge_kind,evidence,refresh_id) 每代内容唯一）。
-- 幂等：可重复执行（已去重则 DELETE 0 行；约束已存在则跳过）。
-- 执行：psql -d nexus_mem -f 004_readmodel_edge_constraints.sql

BEGIN;

-- ① 去重（B2 合规：带 WHERE；完全同内容口径 = 1547 定义的五列全同）
DELETE FROM readmodel_edge a
USING (
    SELECT ctid,
           row_number() OVER (
               PARTITION BY src_identity, dst_identity, edge_kind, evidence, refresh_id
               ORDER BY ctid
           ) AS rn
    FROM readmodel_edge
) d
WHERE a.ctid = d.ctid AND d.rn > 1;

-- ② evidence 非空（Task1570 勘察：0 NULL / max 178B，btree 安全）
ALTER TABLE readmodel_edge ALTER COLUMN evidence SET NOT NULL;

-- ③ 代理主键（原表无 id 列；BY DEFAULT 而非 ALWAYS 便于 pg_dump 恢复显式插值）
ALTER TABLE readmodel_edge ADD COLUMN IF NOT EXISTS id bigint
    GENERATED BY DEFAULT AS IDENTITY;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'readmodel_edge_pkey') THEN
        ALTER TABLE readmodel_edge ADD CONSTRAINT readmodel_edge_pkey PRIMARY KEY (id);
    END IF;
END $$;

-- ④ 业务唯一键（写入方语义锚：refresh_readmodel.py:82 代际替换 + :156 内容元组插入）
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uq_readmodel_edge_content') THEN
        ALTER TABLE readmodel_edge ADD CONSTRAINT uq_readmodel_edge_content
            UNIQUE (src_identity, dst_identity, edge_kind, evidence, refresh_id);
    END IF;
END $$;

COMMIT;
